package com.tradingplatform.persistence;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="paper_accounts") public class PaperAccountEntity { @Id public UUID id; @Column(name="initial_balance") public BigDecimal initialBalance; @Column(name="available_cash") public BigDecimal availableCash; @Column(name="used_margin") public BigDecimal usedMargin; @Column(name="realized_pnl") public BigDecimal realizedPnl; @Column(name="daily_realized_pnl") public BigDecimal dailyRealizedPnl; @Column(name="created_at") public Instant createdAt; @Column(name="updated_at") public Instant updatedAt; }
